import{_ as e,o as n,c as s,ai as i}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Python 面试 · 进阶特性","description":"","frontmatter":{},"headers":[],"relativePath":"guide/python/advanced-interview.md","filePath":"guide/python/advanced-interview.md"}'),t={name:"guide/python/advanced-interview.md"};function r(l,a,d,o,c,h){return n(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="python-面试-·-进阶特性" tabindex="-1">Python 面试 · 进阶特性 <a class="header-anchor" href="#python-面试-·-进阶特性" aria-label="Permalink to “Python 面试 · 进阶特性”">​</a></h1><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>装饰器原理？能写个简单的吗？</li><li>生成器与迭代器关系？</li><li>GIL 对你选型的影响？</li><li><code>*args</code> / <code>**kwargs</code> 与解包？</li><li>上下文管理器 <code>with</code> 是什么？</li><li>面向对象：继承、<code>super</code>、鸭子类型？</li><li><code>@staticmethod</code> / <code>@classmethod</code> / 实例方法？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-装饰器" tabindex="-1">1）装饰器 <a class="header-anchor" href="#_1-装饰器" aria-label="Permalink to “1）装饰器”">​</a></h3><p>本质：接收函数、返回新函数（或可调用对象）。<br> 常用：日志、鉴权、重试、计时。<br> 要点：用 <code>functools.wraps</code> 保留原函数元信息。</p><p>口述可以背结构：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def deco(fn):</span></span>
<span class="line"><span>    def wrapper(*args, **kwargs):</span></span>
<span class="line"><span>        # before</span></span>
<span class="line"><span>        result = fn(*args, **kwargs)</span></span>
<span class="line"><span>        # after</span></span>
<span class="line"><span>        return result</span></span>
<span class="line"><span>    return wrapper</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>带参数的装饰器再包一层——知道有这回事即可。</p><h3 id="_2-生成器" tabindex="-1">2）生成器 <a class="header-anchor" href="#_2-生成器" aria-label="Permalink to “2）生成器”">​</a></h3><p>实现了迭代协议；<code>yield</code> 产出值并暂停。<br> 对比一次返回大 list：省内存、可流水线。<br><code>for</code> 背后是迭代器协议（<code>__iter__</code> / <code>__next__</code>）。</p><h3 id="_3-gil" tabindex="-1">3）GIL <a class="header-anchor" href="#_3-gil" aria-label="Permalink to “3）GIL”">​</a></h3><ul><li>CPU 密集：多线程加速有限 → <code>multiprocessing</code> 或把重计算放到 Java/原生扩展。</li><li>IO 密集：等网络/磁盘时会释放 GIL，多线程或 asyncio 有收益。<br> 面试金句：<strong>先分清瓶颈是 CPU 还是 IO。</strong></li></ul><h3 id="_4-解包" tabindex="-1">4）解包 <a class="header-anchor" href="#_4-解包" aria-label="Permalink to “4）解包”">​</a></h3><p><code>*</code> 拆序列，<code>**</code> 拆字典；拼参数、合并 dict（注意覆盖）常用。</p><h3 id="_5-with" tabindex="-1">5）<code>with</code> <a class="header-anchor" href="#_5-with" aria-label="Permalink to “5）with”">​</a></h3><p>上下文管理器：保证进入/退出（关文件、释锁、关连接）。<br><code>with open(...) as f</code> 比手写 <code>open/close</code> 更安全。</p><h3 id="_6-oop-口述" tabindex="-1">6）OOP 口述 <a class="header-anchor" href="#_6-oop-口述" aria-label="Permalink to “6）OOP 口述”">​</a></h3><ul><li>一切皆对象；鸭子类型：「像就会用」，靠约定而非强接口（也可 Protocol/ABC）。</li><li>多继承存在，实际少用钻石继承炫技。</li><li><code>super()</code> 按 MRO 找父类方法。</li></ul><h3 id="_7-三种方法" tabindex="-1">7）三种方法 <a class="header-anchor" href="#_7-三种方法" aria-label="Permalink to “7）三种方法”">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>第一个参数</th><th>用途</th></tr></thead><tbody><tr><td>实例方法</td><td>self</td><td>普通行为</td></tr><tr><td>classmethod</td><td>cls</td><td>工厂方法、改类级状态</td></tr><tr><td>staticmethod</td><td>无</td><td>挂在类命名空间的函数</td></tr></tbody></table><hr><h2 id="追问预备" tabindex="-1">追问预备 <a class="header-anchor" href="#追问预备" aria-label="Permalink to “追问预备”">​</a></h2><ul><li>「协程和生成器？」→ async/await 是协程；生成器是迭代工具，别混为一谈。</li><li>「类型注解？」→ 提示与工具检查用，运行时默认不强制（除非 pydantic 等）。</li></ul>`,26)])])}const _=e(t,[["render",r]]);export{b as __pageData,_ as default};
